#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Generate the addon language data from shared/i18n/addon/addon.yaml."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "shared" / "i18n" / "addon" / "addon.yaml"
TARGET = ROOT / "addon" / "HordesOfAzeroth" / "VanillaBonkLocaleData.lua"
LOCALES = ("enUS", "zhCN", "zhTW")

BANNER = (
    "-- Generated by tools/i18n/gen_addon_locale.py from\n"
    "-- shared/i18n/addon/addon.yaml. Do not edit by hand.\n"
)


def lua_string(text: str) -> str:
    escaped = (
        text.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
    )
    return f'"{escaped}"'


def load_entries() -> list[tuple[str, str, dict]]:
    data = yaml.safe_load(SOURCE.read_text(encoding="utf-8"))
    if not isinstance(data, list):
        raise SystemExit("addon.yaml: top level must be a list")
    seen: set[str] = set()
    seen_ids: set[str] = set()
    entries = []
    for entry in data:
        key = entry.get("enUS")
        message_id = entry.get("id")
        if not isinstance(key, str) or not isinstance(message_id, str) or not message_id:
            raise SystemExit(f"addon.yaml: entry without enUS/id: {message_id}")
        if key in seen:
            raise SystemExit(f"addon.yaml: duplicate enUS key: {key!r}")
        if message_id in seen_ids:
            raise SystemExit(f"addon.yaml: duplicate id: {message_id!r}")
        seen.add(key)
        seen_ids.add(message_id)
        entries.append((message_id, key, entry))
    return sorted(entries, key=lambda item: item[0])


def render(entries: list[tuple[str, str, dict]]) -> bytes:
    lines = [BANNER, "VanillaBonkLocale.RegisterLanguages({"]
    for locale in LOCALES:
        lines.append(f"    {locale} = {{")
        for message_id, _key, entry in entries:
            value = entry.get(locale)
            if isinstance(value, str):
                lines.append(f"        [{lua_string(message_id)}] = {lua_string(value)},")
        lines.append("    },")
    lines.append("})")
    lines += ["VanillaBonkLocale.RegisterKeys({"]
    for message_id, key, _entry in entries:
        lines.append(f"    [{lua_string(key)}] = {lua_string(message_id)},")
    lines.append("})")
    lines += ["VanillaBonkLocale.RegisterEnglish({"]
    for message_id, key, _entry in entries:
        lines.append(f"    [{lua_string(message_id)}] = {lua_string(key)},")
    lines.append("})")
    lines.append("")
    return "\n".join(lines).encode("utf-8")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="fail if the Lua data differs")
    args = parser.parse_args()
    rendered = render(load_entries())
    if args.check:
        current = TARGET.read_bytes() if TARGET.exists() else b""
        if current != rendered:
            print(
                "addon locale data is out of date; "
                "run tools/i18n/gen_addon_locale.py"
            )
            return 1
        print("addon locale data: generated from shared/i18n/addon/addon.yaml")
        return 0
    TARGET.write_bytes(rendered)
    print(f"wrote {TARGET.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
